from collections import deque
import sys

def _dinic_cutoff(nH, hadj, others, x, y, limit):
    # hadj: list of dict v->cap for H nodes 0..nH-1
    # others: list (C, iterable(V))
    n = nH + len(others)
    adj=[[] for _ in range(n)]
    to=[]; cap=[]
    def add(u,v,c):
        adj[u].append(len(to));to.append(v);cap.append(c)
        adj[v].append(len(to));to.append(u);cap.append(0)
    for u in range(nH):
        for v,c in hadj[u].items():
            if c>0:
                add(u,v,c if c<limit else limit)
    sbase=nH
    for i,(C,V) in enumerate(others):
        s=sbase+i
        c=C if C<limit else limit
        add(x,s,c)
        for v in V:
            add(s,v,limit)
    if x==y:
        return limit
    level=[-1]*n;it=[0]*n
    flow=0
    def bfs():
        for i in range(n):level[i]=-1
        level[x]=0;q=deque([x])
        while q:
            u=q.popleft();nu=level[u]+1
            for e in adj[u]:
                if cap[e]>0:
                    v=to[e]
                    if level[v]<0:
                        level[v]=nu;q.append(v)
        return level[y]>=0
    old=sys.getrecursionlimit()
    if old<n+100:sys.setrecursionlimit(n+1000)
    def dfs(u,f):
        if u==y:return f
        au=adj[u];i=it[u]
        while i<len(au):
            e=au[i];v=to[e]
            if cap[e]>0 and level[v]==level[u]+1:
                z=f if f<cap[e] else cap[e]
                r=dfs(v,z)
                if r:
                    cap[e]-=r;cap[e^1]+=r;it[u]=i
                    return r
            i+=1;it[u]=i
        return 0
    while flow<limit and bfs():
        for i in range(n):it[i]=0
        while flow<limit:
            f=dfs(x,limit-flow)
            if not f:break
            flow+=f
    if old<n+100:sys.setrecursionlimit(old)
    return flow

class GenFast:
    def __init__(self,H,participants,roots):
        self.P=sorted(participants)
        self.idx={v:i for i,v in enumerate(self.P)}
        k=len(self.P);self.k=k
        self.Hadj=[{} for _ in range(k)]
        for a,b,d in H.edges(data=True):
            if a not in self.idx or b not in self.idx:continue
            c=d.get('capacity',0)
            if c>0:
                u=self.idx[a];v=self.idx[b]
                self.Hadj[u][v]=self.Hadj[u].get(v,0)+c
        self.roots={self.idx[u]:c for u,c in roots.items() if c>0}
        self.D=sum(self.roots.values())
        self.all=set(range(k))
        # active tree data keyed (root,sernum)
        self.Cs={};self.Vs={};self.Ts={};self.roots_of={}
        self.active={}  # key -> sid
        self.sid=0
        self.tcount={}
        q=deque()
        for u in sorted(self.roots):
            key=(u,0);self.tcount[u]=1
            self.Cs[key]=self.roots[u];self.Vs[key]={u};self.Ts[key]=[];self.roots_of[key]=u
            self.active[key]=self.sid;self.sid+=1;q.append(key)
        self.q=q
        self.max_active=0
        self.max_edges=0
    def new_tree(self,root,edges,nodes,C):
        idx=self.tcount[root];self.tcount[root]=idx+1
        key=(root,idx)
        self.Cs[key]=C;self.Vs[key]=set(nodes);self.Ts[key]=list(edges);self.roots_of[key]=root
        self.active[key]=self.sid;self.sid+=1
        self.q.append(key)
        return key
    def test_edge(self,key,x,y):
        C=self.Cs[key];capxy=self.Hadj[x].get(y,0)
        if capxy<=0 or C<=0:return 0
        others=[];csum=0
        for k2,sid in self.active.items():
            if k2==key:continue
            c=self.Cs[k2];
            if c>0:
                others.append((c,tuple(self.Vs[k2])));csum+=c
        self.max_active=max(self.max_active,len(self.active))
        self.max_edges=max(self.max_edges,sum(len(a) for a in self.Hadj)+len(others)+sum(len(v) for c,v in others))
        lim=csum+min(C,capxy)
        val=_dinic_cutoff(self.k,self.Hadj,others,x,y,lim)
        return max(0,min(C,capxy,val-csum))
    def generate(self):
        while self.q:
            key=self.q.popleft();root=self.roots_of[key]
            bfs=deque(sorted(self.Vs[key]))
            while bfs:
                x=bfs.popleft()
                # iterate H adjacency snapshot sorted
                for y in sorted(list(self.Hadj[x].keys())):
                    if y in self.Vs[key]:continue
                    capxy=self.Hadj[x].get(y,0)
                    if capxy<=0:continue
                    chunks=self.test_edge(key,x,y)
                    if chunks<=0:continue
                    bfs.append(y)
                    if chunks<self.Cs[key]:
                        nk=self.new_tree(root,self.Ts[key],self.Vs[key],self.Cs[key]-chunks)
                        self.Cs[key]=chunks
                    self.Ts[key].append((x,y));self.Vs[key].add(y)
                    c=self.Hadj[x][y]-chunks
                    if c==0:del self.Hadj[x][y]
                    else:self.Hadj[x][y]=c
            if len(self.Vs[key])!=self.k:
                raise Exception(('partial',len(self.Vs[key]),self.k))
            if len(self.Ts[key])!=self.k-1:
                raise Exception(('edge count',len(self.Ts[key])))
            del self.active[key]
        sums={u:0 for u in self.roots}
        for key,C in self.Cs.items():sums[self.roots_of[key]]+=C
        for u,c in self.roots.items():
            if sums.get(u,0)!=c:raise Exception(('sum',u,sums.get(u,0),c))
        return self.Ts,self.Cs
